package net.zartra.gui;
import org.bukkit.*;import org.bukkit.enchantments.Enchantment;import org.bukkit.inventory.*;import org.bukkit.inventory.meta.ItemMeta;import java.util.*;
final class MenuItem {String material;int data;int amount;String name;List<String> lore;boolean glow;boolean hideEnchantments;boolean unbreakable;int customModelData=-1;String headOwner="";String leatherColor="";String potionData="";boolean leatherDefault;Map<String,Object> stackSnapshot=new LinkedHashMap<String,Object>();/* Active editor operations retain an opaque runtime clone; persistence uses stackSnapshot only. */private transient ItemStack runtimeStack;final Map<String,Integer> enchantments=new TreeMap<String,Integer>();boolean closeAfterAction;long cooldown;int priority;String fallbackMaterial="";MenuAction action;final ConditionSet conditions=new ConditionSet();final Map<MenuClickType,List<ActionEntry>> actions=new EnumMap<MenuClickType,List<ActionEntry>>(MenuClickType.class);
MenuItem(ItemStack stack,MenuAction legacy){capture(stack);action=legacy;}static MenuItem runtime(ItemStack stack){MenuItem item=new MenuItem(new ItemStack(Material.AIR),null);item.runtimeStack=stack==null?new ItemStack(Material.AIR):stack.clone();item.material=CompatMaterial.name(item.runtimeStack.getType());item.data=item.runtimeStack.getDurability();item.amount=Math.max(1,item.runtimeStack.getAmount());item.stackSnapshot.clear();ItemMeta meta=null;try{meta=item.runtimeStack.getItemMeta();}catch(Throwable ignored){}item.name=meta!=null&&meta.hasDisplayName()?meta.getDisplayName():null;item.lore=meta!=null&&meta.hasLore()?new ArrayList<String>(meta.getLore()):new ArrayList<String>();item.glow=meta!=null&&meta.hasEnchants();return item;}void preparePersistence(){if(runtimeStack==null)return;try{stackSnapshot=copyMap(runtimeStack.serialize());}catch(Throwable ignored){if(stackSnapshot==null)stackSnapshot=new LinkedHashMap<String,Object>();}}
void capture(ItemStack stack){if(stack==null)stack=new ItemStack(Material.AIR);runtimeStack=stack.clone();material=CompatMaterial.name(stack.getType());data=stack.getDurability();amount=Math.max(1,stack.getAmount());try{stackSnapshot=copyMap(stack.serialize());}catch(Throwable ignored){stackSnapshot=new LinkedHashMap<String,Object>();stackSnapshot.put("type",material);stackSnapshot.put("amount",Integer.valueOf(amount));stackSnapshot.put("damage",Short.valueOf((short)data));}ItemMeta m=null;try{m=stack.getItemMeta();}catch(Throwable ignored){}name=m!=null&&m.hasDisplayName()?m.getDisplayName():null;lore=m!=null&&m.hasLore()?new ArrayList<String>(m.getLore()):new ArrayList<String>();glow=m!=null&&m.hasEnchants();}
@SuppressWarnings("unchecked") private static Object copyValue(Object value){if(value instanceof Map){Map<String,Object> out=new LinkedHashMap<String,Object>();for(Map.Entry<?,?> e:((Map<?,?>)value).entrySet())out.put(String.valueOf(e.getKey()),copyValue(e.getValue()));return out;}if(value instanceof List){List<Object> out=new ArrayList<Object>();for(Object x:(List<?>)value)out.add(copyValue(x));return out;}return value;}@SuppressWarnings("unchecked") static Map<String,Object> copyMap(Map<?,?> source){Map<String,Object> out=new LinkedHashMap<String,Object>();if(source!=null)for(Map.Entry<?,?> e:source.entrySet())out.put(String.valueOf(e.getKey()),copyValue(e.getValue()));return out;}
ItemStack stack(){ItemStack out=null;/* Never deserialize a live Paper runtime item during a virtual editor transaction. */try{if(runtimeStack!=null)out=runtimeStack.clone();}catch(Throwable ignored){}try{if(out==null&&stackSnapshot!=null&&!stackSnapshot.isEmpty())out=ItemStack.deserialize(copyMap(stackSnapshot));}catch(Throwable ignored){}Material resolved=CompatMaterial.findOrNull(material);if(resolved==null)resolved=CompatMaterial.findOrNull(fallbackMaterial);if(out==null||out.getType()==Material.AIR){if(resolved==null)resolved=Material.BARRIER;out=new ItemStack(resolved,amount,(short)data);}else{try{out.setAmount(amount);}catch(Throwable ignored){}}ItemMeta meta=null;try{meta=out.getItemMeta();}catch(Throwable ignored){}if(meta!=null){if(name!=null)meta.setDisplayName(Chat.c(name));if(lore!=null&&!lore.isEmpty()){List<String>x=new ArrayList<String>();for(String s:lore)x.add(Chat.c(s));meta.setLore(x);}if(glow)meta.addEnchant(Enchantment.DURABILITY,1,true);for(Map.Entry<String,Integer>e:enchantments.entrySet())try{Enchantment enchant=Enchantment.getByName(e.getKey());if(enchant!=null)meta.addEnchant(enchant,e.getValue(),true);}catch(Throwable ignored){}CompatItemMeta.apply(meta,this);out.setItemMeta(meta);}return out;}
List<ActionEntry> actions(MenuClickType type){List<ActionEntry> list=actions.get(type);if(list==null){list=new ArrayList<ActionEntry>();actions.put(type,list);}Collections.sort(list,new Comparator<ActionEntry>(){public int compare(ActionEntry a,ActionEntry b){return a.order-b.order;}});return list;}void copyRuntimeFrom(MenuItem o){if(o==null)return;hideEnchantments=o.hideEnchantments;unbreakable=o.unbreakable;customModelData=o.customModelData;headOwner=o.headOwner;leatherColor=o.leatherColor;leatherDefault=o.leatherDefault;potionData=o.potionData;enchantments.putAll(o.enchantments);closeAfterAction=o.closeAfterAction;cooldown=o.cooldown;priority=o.priority;fallbackMaterial=o.fallbackMaterial;conditions.mode=o.conditions.mode;conditions.hideWhenFail=o.conditions.hideWhenFail;conditions.disableClick=o.conditions.disableClick;conditions.stopChain=o.conditions.stopChain;conditions.failureMessage=o.conditions.failureMessage;conditions.replacementMaterial=o.conditions.replacementMaterial;for(ActionEntry a:o.conditions.successActions)conditions.successActions.add(a.copy());for(ActionEntry a:o.conditions.failureActions)conditions.failureActions.add(a.copy());for(ConditionEntry c:o.conditions.entries)conditions.entries.add(c.copy());for(MenuClickType t:MenuClickType.values())for(ActionEntry a:o.actions(t))actions(t).add(a.copy());}MenuItem appearanceCopy(){MenuItem n=new MenuItem(stack(),null);return n;}MenuItem copy(){MenuItem n=appearanceCopy();n.material=material;n.data=data;n.amount=amount;n.name=name;n.lore=lore==null?new ArrayList<String>():new ArrayList<String>(lore);n.glow=glow;n.leatherDefault=leatherDefault;n.stackSnapshot=copyMap(stackSnapshot);n.copyRuntimeFrom(this);return n;}void migrateLegacy(){if(action!=null&&actions.isEmpty()){ActionEntry x=new ActionEntry();x.type=action.type.name();x.value=action.value;x.order=0;actions(MenuClickType.LEFT).add(x);}action=null;}}